/**
 * CSE 2210: Token Stream Inspector Component
 * Shows lexical tokens generated by the Flex lexer specification.
 */

import React, { useState } from 'react';
import { Token, TokenType } from '../compiler/types';
import { ListFilter, Search } from 'lucide-react';

interface TokenStreamViewerProps {
  tokens: Token[];
  onSelectLine?: (line: number) => void;
}

export const TokenStreamViewer: React.FC<TokenStreamViewerProps> = ({ tokens, onSelectLine }) => {
  const [filterType, setFilterType] = useState<string>('ALL');
  const [search, setSearch] = useState('');

  const tokenTypes: { label: string; value: string }[] = [
    { label: 'All', value: 'ALL' },
    { label: 'Keywords', value: 'KEYWORD' },
    { label: 'Identifiers', value: 'IDENTIFIER' },
    { label: 'Literals', value: 'LITERAL' },
    { label: 'Operators', value: 'OPERATOR' },
    { label: 'Punctuation', value: 'PUNCTUATION' },
  ];

  const filteredTokens = tokens.filter((t) => {
    if (t.type === 'EOF') return false;

    let matchesType = true;
    if (filterType === 'LITERAL') {
      matchesType =
        t.type === 'INT_LITERAL' ||
        t.type === 'FLOAT_LITERAL' ||
        t.type === 'STRING_LITERAL' ||
        t.type === 'BOOL_LITERAL';
    } else if (filterType !== 'ALL') {
      matchesType = t.type === filterType;
    }

    const matchesSearch =
      t.value.toLowerCase().includes(search.toLowerCase()) ||
      t.type.toLowerCase().includes(search.toLowerCase());

    return matchesType && matchesSearch;
  });

  return (
    <div className="flex flex-col h-full bg-slate-900/40 rounded-xl border border-slate-800 overflow-hidden">
      {/* Controls */}
      <div className="p-3 bg-slate-900/90 border-b border-slate-800 flex flex-wrap items-center justify-between gap-3 text-xs">
        <div className="relative w-48">
          <Search className="w-3.5 h-3.5 absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" />
          <input
            type="text"
            placeholder="Search lexeme..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-950 border border-slate-800 rounded-md pl-8 pr-3 py-1 text-xs text-slate-200 placeholder-slate-500 focus:outline-none focus:border-sky-500"
          />
        </div>

        <div className="flex items-center gap-1.5 overflow-x-auto bg-slate-950 p-0.5 rounded-lg border border-slate-800">
          <ListFilter className="w-3.5 h-3.5 text-slate-500 ml-1.5" />
          {tokenTypes.map((t) => (
            <button
              key={t.value}
              onClick={() => setFilterType(t.value)}
              className={`px-2 py-0.5 rounded text-[11px] whitespace-nowrap transition-colors ${
                filterType === t.value
                  ? 'bg-slate-800 text-sky-400 font-medium'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      {/* Token List */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left text-xs border-collapse">
          <thead>
            <tr className="bg-slate-950/80 text-slate-400 border-b border-slate-800 font-medium sticky top-0 z-10">
              <th className="py-2 px-3 w-16">#</th>
              <th className="py-2 px-3">Token Type</th>
              <th className="py-2 px-3">Lexeme Value</th>
              <th className="py-2 px-3">Line</th>
              <th className="py-2 px-3">Column</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/60 font-mono text-[11px]">
            {filteredTokens.map((tok, index) => {
              let badgeColor = 'bg-slate-800 text-slate-300';
              if (tok.type === 'KEYWORD') badgeColor = 'bg-purple-950/70 text-purple-300 border border-purple-800/50';
              else if (tok.type === 'IDENTIFIER') badgeColor = 'bg-sky-950/70 text-sky-300 border border-sky-800/50';
              else if (tok.type.endsWith('_LITERAL')) badgeColor = 'bg-emerald-950/70 text-emerald-300 border border-emerald-800/50';
              else if (tok.type === 'OPERATOR') badgeColor = 'bg-amber-950/70 text-amber-300 border border-amber-800/50';
              else if (tok.type === 'PUNCTUATION') badgeColor = 'bg-slate-800/80 text-slate-400';

              return (
                <tr
                  key={tok.id || index}
                  onClick={() => onSelectLine && onSelectLine(tok.line)}
                  className="hover:bg-slate-800/40 cursor-pointer transition-colors"
                >
                  <td className="py-2 px-3 text-slate-400 tabular-nums">{index + 1}</td>
                  <td className="py-2 px-3 font-sans">
                    <span className={`px-2 py-0.5 rounded text-[10px] font-medium ${badgeColor}`}>
                      {tok.type}
                    </span>
                  </td>
                  <td className="py-2 px-3 text-slate-200 font-semibold truncate max-w-xs">
                    {tok.type === 'STRING_LITERAL' ? `"${tok.value}"` : tok.value}
                  </td>
                  <td className="py-2 px-3 text-sky-400 font-sans tabular-nums">line {tok.line}</td>
                  <td className="py-2 px-3 text-slate-400 font-sans tabular-nums">col {tok.column}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="px-4 py-2 bg-slate-950/80 border-t border-slate-800 text-[11px] text-slate-400">
        Total Tokens Generated: <strong className="text-slate-200 font-mono">{filteredTokens.length}</strong>
      </div>
    </div>
  );
};
